cd /Users/bymyway/.openclaw && python3 -c "
import json
d = json.load(open('openclaw.json'))
def find_key(obj, key, path=''):
    results=[]
    if isinstance(obj, dict):
        for k,v in obj.items():
            newpath = f'{path}.{k}' if path else k
            if key.lower() in k.lower():
                results.append((newpath, v if not isinstance(v,(dict,list)) else '...'))
            results += find_key(v, key, newpath)
    elif isinstance(obj, list):
        for i,v in enumerate(obj):
            results += find_key(v, key, f'{path}[{i}]')
    return results
for k in ['memorySearch','memsearch','vector','plugin']:
    print('===', k, '===')
    for p,v in find_key(d, k):
        print(p, '=', v)
"

