def find_key(obj,key,path=''):
    r=[]
    if isinstance(obj,dict):
        for k,v in obj.items():
            p=f'{path}.{k}' if path else k
            if key.lower() in k.lower(): r.append((p, v if not isinstance(v,(dict,list)) else '...'))
            r+=find_key(v,key,p)
